final class LoopinStatus extends ffi.Struct {
  /// 1 si el audio está funcionando
  @ffi.Int32()
  external int running;

  /// Hz
  @ffi.Int32()
  external int sample_rate;

  /// tamaño del bloque del dispositivo
  @ffi.Int32()
  external int frames_per_burst;

  /// tamaño del buffer de salida en uso
  @ffi.Int32()
  external int buffer_size_frames;

  /// LOOPIN_API_*
  @ffi.Int32()
  external int audio_api;

  /// 1 = modo exclusivo (menos latencia)
  @ffi.Int32()
  external int exclusive;

  /// 1 = ruta de baja latencia concedida
  @ffi.Int32()
  external int low_latency;

  @ffi.Int32()
  external int input_channels;

  @ffi.Int32()
  external int output_channels;

  /// LOOPIN_PRESET_* que está usando la entrada
  @ffi.Int32()
  external int input_preset;

  /// 1 si el modo pedido falló y se usó otro
  @ffi.Int32()
  external int preset_fallback;

  /// id del dispositivo de entrada en uso (Android)
  @ffi.Int32()
  external int input_device_id;

  /// id del dispositivo de salida en uso
  @ffi.Int32()
  external int output_device_id;

  /// cortes de la salida (-1 si no se sabe)
  @ffi.Int32()
  external int xrun_count;

  /// 1 si se desconectó un dispositivo
  @ffi.Int32()
  external int disconnected;

  /// estimación de Oboe (-1 si no se sabe)
  @ffi.Double()
  external double output_latency_ms;

  /// estimación de Oboe (-1 si no se sabe)
  @ffi.Double()
  external double input_latency_ms;

  /// Transporte / metrónomo
  @ffi.Int32()
  external int playing;

  /// compás actual (empieza en 0)
  @ffi.Int32()
  external int bar;

  /// tiempo dentro del compás (empieza en 0)
  @ffi.Int32()
  external int beat;

  @ffi.Int32()
  external int beats_per_bar;

  @ffi.Int32()
  external int samples_per_beat;

  @ffi.Double()
  external double bpm;

  /// muestras desde que arrancó el transporte
  @ffi.Int64()
  external int frame_position;

  /// 0..1, con caída lenta
  @ffi.Float()
  external double input_peak;

  /// LOOPIN_LATENCY_*
  @ffi.Int32()
  external int latency_state;

  /// clics detectados hasta ahora
  @ffi.Int32()
  external int latency_progress;

  /// resultado en muestras
  @ffi.Int32()
  external int latency_frames;

  /// resultado en ms
  @ffi.Double()
  external double latency_ms;

  /// Entrada (diagnóstico de latencia)
  @ffi.Int32()
  external int input_frames_per_burst;

  @ffi.Int32()
  external int input_buffer_frames;

  @ffi.Int32()
  external int input_exclusive;

  @ffi.Int32()
  external int input_low_latency;

  /// máx. muestras leídas en un callback (últimos ~2 s)
  @ffi.Int32()
  external int input_max_read;

  /// LOOPIN_LOOP_*
  @ffi.Int32()
  external int loop_state;

  /// LOOPIN_MODE_*
  @ffi.Int32()
  external int loop_mode;

  /// compases del modo sincronizado
  @ffi.Int32()
  external int loop_sync_bars;

  /// capas que suenan (el loop base cuenta como 1)
  @ffi.Int32()
  external int loop_layers;

  @ffi.Int32()
  external int loop_can_undo;

  /// compensación que se está aplicando
  @ffi.Int32()
  external int loop_latency_frames;

  /// muestras (0 = sin loop)
  @ffi.Int64()
  external int loop_length;

  /// posición de reproducción en muestras
  @ffi.Int64()
  external int loop_position;

  /// armado: negativo (falta para grabar); grabando: grabado
  @ffi.Int64()
  external int loop_recorded;

  /// grabando: longitud a la que se cerrará (0 = abierta)
  @ffi.Int64()
  external int loop_target;

  /// muestras por compás del loop
  @ffi.Int64()
  external int loop_bar_frames;

  /// pista que usará el siguiente toque (0..3)
  @ffi.Int32()
  external int loop_selected;

  /// pista en la que se graba (-1 si ninguna)
  @ffi.Int32()
  external int loop_active;

  /// 1 = tras grabar una pista se elige la siguiente vacía
  @ffi.Int32()
  external int loop_auto_advance;

  /// duración base en muestras (0 = no hay loops)
  @ffi.Int64()
  external int loop_base_length;

  /// posición dentro del ciclo base
  @ffi.Int64()
  external int loop_base_position;

  /// LOOPIN_LOOP_*
  @ffi.Array.multi([4])
  external ffi.Array<ffi.Int32> track_state;

  @ffi.Array.multi([4])
  external ffi.Array<ffi.Int32> track_layers;

  @ffi.Array.multi([4])
  external ffi.Array<ffi.Int32> track_muted;

  @ffi.Array.multi([4])
  external ffi.Array<ffi.Float> track_volume;

  /// 1, 2 o 4 veces la base (0 = vacía)
  @ffi.Array.multi([4])
  external ffi.Array<ffi.Int64> track_length;

  @ffi.Array.multi([4])
  external ffi.Array<ffi.Int64> track_position;

  /// muestras ya sonadas del tiempo actual
  @ffi.Int32()
  external int beat_frames;

  /// tiempos con acento medio (bit k = tiempo k)
  @ffi.Int32()
  external int accent_mask;

  /// LOOPIN_CLICK_*
  @ffi.Int32()
  external int click_mode;

  @ffi.Int32()
  external int start_on_sound;

  /// 1 = esperando a que suene la guitarra
  @ffi.Int32()
  external int loop_waiting;

  /// LOOPIN_LATENCY_* (mismos valores)
  @ffi.Int32()
  external int tap_state;

  /// clics que ya han sonado (de 16)
  @ffi.Int32()
  external int tap_clicks;

  /// golpes que cuentan (de 12)
  @ffi.Int32()
  external int tap_hits;

  /// resultado en muestras
  @ffi.Int32()
  external int tap_frames;

  /// dispersión de los golpes en muestras
  @ffi.Int32()
  external int tap_spread;

  /// Carga del callback de audio: fracción del tiempo disponible (1.0 = 100 %;
  /// por encima, el audio se corta)
  /// media del último segundo
  @ffi.Float()
  external double cpu_load_avg;

  /// pico del último segundo
  @ffi.Float()
  external double cpu_load_peak;

  /// mayor pico desde que se abrió el audio
  @ffi.Float()
  external double cpu_load_max;

  /// Batería
  @ffi.Int32()
  external int drums_enabled;

  /// LOOPIN_STYLE_* pedido
  @ffi.Int32()
  external int drum_style;

  /// 1 = ya ha entrado (en un primer tiempo) y suena
  @ffi.Int32()
  external int drums_playing;

  @ffi.Float()
  external double drum_volume;

  /// Audio importado: abrir una canción para prepararla
  @ffi.Int32()
  external int song_open_id;

  /// LOOPIN_JOB_*
  @ffi.Int32()
  external int song_open_state;

  /// 0..1000
  @ffi.Int32()
  external int song_open_progress;

  /// LOOPIN_SONG_ERR_*
  @ffi.Int32()
  external int song_open_error;

  /// duración (a sample_rate)
  @ffi.Int64()
  external int song_open_frames;

  /// tempo sugerido (0 = ni idea)
  @ffi.Double()
  external double song_bpm_guess;

  /// primer golpe claro (muestra; -1 = ninguno)
  @ffi.Int64()
  external int song_first_attack;

  /// Audio importado: preparar la canción para que suene
  @ffi.Int32()
  external int song_prep_id;

  @ffi.Int32()
  external int song_prep_state;

  @ffi.Int32()
  external int song_prep_progress;

  @ffi.Int32()
  external int song_prep_error;

  /// La canción que suena con el transporte
  @ffi.Int32()
  external int backing_enabled;

  @ffi.Int32()
  external int backing_playing;

  @ffi.Int32()
  external int backing_id;

  @ffi.Int32()
  external int backing_samples_per_beat;

  @ffi.Int32()
  external int backing_beats_per_bar;

  @ffi.Int64()
  external int backing_position;

  @ffi.Int64()
  external int backing_length;

  @ffi.Float()
  external double backing_volume;

  /// Vista previa
  @ffi.Int32()
  external int preview_id;

  @ffi.Int32()
  external int preview_playing;

  @ffi.Int32()
  external int preview_click;

  @ffi.Int64()
  external int preview_position;

  @ffi.Int64()
  external int preview_length;

  /// Etapa 5: reverse y media velocidad (lo pedido; puede esperar al 1)
  @ffi.Array.multi([4])
  external ffi.Array<ffi.Int32> track_reverse;

  @ffi.Array.multi([4])
  external ffi.Array<ffi.Int32> track_half;

  /// LOOPIN_PENDING_* (bits)
  @ffi.Array.multi([4])
  external ffi.Array<ffi.Int32> track_pending;

  @ffi.Int32()
  external int quantize;

  /// LOOPIN_STOP_*
  @ffi.Int32()
  external int stop_mode;

  /// 0 no, 1 esperando al 1, 2 bajando (fundido)
  @ffi.Int32()
  external int stopping;

  /// 0 = entrenador apagado
  @ffi.Int32()
  external int trainer_bars;

  @ffi.Double()
  external double trainer_step;

  @ffi.Double()
  external double trainer_top;
}

final class LoopinTuner extends ffi.Struct {
  /// Hz (0 = no hay una nota clara)
  @ffi.Float()
  external double frequency;

  @ffi.Float()
  external double clarity;

  /// nivel de la entrada (dBFS)
  @ffi.Float()
  external double level_db;

  /// 1 si ha llegado audio desde la última lectura
  @ffi.Int32()
  external int fresh;
}

